const orders = $input.all().map(i => i.json).filter(o => o && o.id && o.date_created);
// Store timezone offset derived from the orders' own local vs GMT timestamps
const ref = orders.find(o => o.date_created_gmt);
const offsetMs = ref ? Date.parse(ref.date_created + 'Z') - Date.parse(ref.date_created_gmt + 'Z') : 0;
const todayStr = new Date(Date.now() + offsetMs).toISOString().slice(0, 10);
const today = orders.filter(o => String(o.date_created).slice(0, 10) === todayStr);
const paidStatuses = ['processing', 'completed'];
const paid = today.filter(o => paidStatuses.includes(o.status));
const pending = today.filter(o => o.status === 'pending');
const sales = paid.reduce((s, o) => s + (parseFloat(o.total) || 0), 0);
const currency = (today[0] || orders[0] || {}).currency || 'N/A';
const text = [
  'Sales summary for ' + todayStr + ' (store time)',
  'Total orders today: ' + today.length,
  'Paid orders (processing/completed): ' + paid.length,
  'Pending payment orders: ' + pending.length,
  'Total sales: ' + sales.toFixed(2) + ' ' + currency,
  'Currency: ' + currency
].join('\n');
return [{ json: { text, totalOrders: today.length, paidOrders: paid.length, pendingOrders: pending.length, totalSales: sales, currency } }];

const cmd = $('Parse Price/Stock Command').first().json.psCommand;
const p = $input.first().json;
const esc = s => String(s ?? '-').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const html = String(p.price_html || '');
const sym = html.match(/currencySymbol[^>]*>([^<]*)</);
const currency = sym ? sym[1].replace(/&#(\d+);/g, (m, c) => String.fromCharCode(Number(c))).replace(/&amp;/g, '&') : 'not available';
let text;
if (cmd === 'price') {
  const lines = [
    'Product: ' + esc(p.name),
    'Regular price: ' + esc(p.regular_price || '-'),
    'Current price: ' + esc(p.price || '-')
  ];
  if (p.on_sale && p.sale_price) lines.push('Sale price: ' + esc(p.sale_price));
  lines.push('Currency: ' + esc(currency));
  text = lines.join('\n');
} else {
  const tracked = p.manage_stock === true && p.stock_quantity !== null && p.stock_quantity !== undefined;
  text = [
    'Product: ' + esc(p.name),
    'Stock management: ' + (p.manage_stock === true ? 'Enabled' : 'Disabled'),
    'Stock quantity: ' + (tracked ? p.stock_quantity : 'Stock quantity not tracked'),
    'Stock status: ' + esc(p.stock_status || '-')
  ].join('\n');
}
return [{ json: { text } }];

