const cfg = $('Config and Allowlist').first().json;
const row = $input.first().json || {};
const m = /^(pc|px)_([0-9a-f]{32})$/.exec(String(cfg.callbackData || ''));
let decision = 'invalid';
if (m && row.token && String(row.user_id) === String(cfg.userId) && String(row.chat_id) === String(cfg.chatId) && row.pending_action === 'price_confirm' && String(row.token) === m[2]) {
  decision = Number(row.expires_at) > Date.now() ? (m[1] === 'pc' ? 'confirm' : 'cancel') : 'expired';
}
return [{ json: { decision } }];

const cfg = $('Config and Allowlist').first().json;
const row = $input.first().json || {};
const text = String(cfg.text || '').trim();
const out = (route, extra) => [{ json: Object.assign({}, cfg, { route }, extra || {}) }];
const hasSession = !!row.pending_action && String(row.user_id) === String(cfg.userId) && (!row.chat_id || String(row.chat_id) === String(cfg.chatId));
if (text.startsWith('/') || !hasSession) return out('forward');
if (Number(row.expires_at) < Date.now()) return out('expired');
const pa = row.pending_action;
if (pa === 'update_price') {
  const pid = /^[0-9]+$/.test(text) ? Number(text) : 0;
  if (!Number.isSafeInteger(pid) || pid <= 0) return out('invalid');
  return out('price_lookup', { productId: String(pid) });
}
if (pa === 'update_price_new') {
  // PRICE_DECIMALS: store currency precision is assumed to be 2 (not read from WooCommerce settings)
  const ok = /^(0|[1-9][0-9]{0,11})([.][0-9]{1,2})?$/.test(text) && Number.isFinite(Number(text));
  if (!ok) return out('price_invalid');
  return out('price_propose', { productId: row.product_id, productName: row.product_name, originalPrice: row.original_price, newPrice: Number(text).toFixed(2) });
}
if (pa === 'price_confirm') return out('price_wait');
const commands = { order: '/order', product: '/product', price: '/price', stock: '/stock' };
const cmd = commands[row.pending_action];
if (!cmd) return out('expired');
const n = /^[0-9]+$/.test(text) ? Number(text) : 0;
if (!Number.isSafeInteger(n) || n <= 0) return out('invalid');
return out('valid', { text: cmd + ' ' + n });

